import {EARLY_BIRD_END,earlyBirdDiscount,campTotal} from './pricing.js';
import {config} from './config.js';
import {refundHtml} from './refund.js';
const $=s=>document.querySelector(s),money=n=>'NT$ '+n.toLocaleString('zh-TW'),line='https://lin.ee/NTY6jV8';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let camps=[];const main=$('#main');
const date=s=>s.slice(5).replace('-','/');
const priceMarkup=base=>`<span data-base-price="${base}">${earlyBirdDiscount()?`<del class="original-price">${money(base)}</del> <span class="early-price">${money(campTotal(base))}<small> 早鳥價</small></span>`:money(base)}</span>`;
const enroll=(c,p='')=>`register.html?camp=${c.id}${p?'&plan='+p:''}`;
const common=()=>`<div class="info-grid"><div class="panel"><h3>一天的節奏</h3><p>09:00–16:00 上課，包含午餐與午休。<br>08:30–09:00 一般到班。<br>08:00–08:30 早托須預約，每天 100 元。<br>不提供點心，孩子可自行攜帶。</p></div><div class="panel"><h3>安心接送</h3><p>16:00–17:30 免費留班等候接回。<br>17:30 後每半小時 100 元，不足半小時以半小時計，最晚 19:00 接回。</p></div><div class="panel"><h3>在萬華，一起動手做</h3><p>創意方塊機器人教室<br>台北市萬華區莒光路347巷20號1樓<br><a href="https://maps.app.goo.gl/XbzyMSb3q2zswpJj8">開啟 Google 地圖 ↗</a></p></div><div class="panel"><h3>小班，讓探索有空間</h3><p>1 人即開班，每班最多 5 人。三個營隊皆可零經驗參加；遙控車營仍須符合年級或組裝能力條件。</p></div></div>`;
const process=()=>`<div class="steps"><div class="step"><b>01 / 選擇與填寫</b><h3>找到適合孩子的營隊</h3><p>選定營隊、方案與早托日期，填寫一位孩子的報名資料。</p></div><div class="step"><b>02 / LINE 聯絡</b><h3>讓老師找到你的報名</h3><p>收到收件編號後，加入 LINE 並傳送孩子姓名與編號，確認名額與付款資訊。</p></div><div class="step"><b>03 / 教室確認</b><h3>完成繳費，準備出發</h3><p>完成繳費並收到教室確認，才算完成報名。表單收件不等於保留名額。</p></div></div>`;
function home(){main.innerHTML=`<section class="hero"><div class="wrap hero-grid"><div class="hero-copy"><div class="eyebrow">2027 WINTER CAMP · 台北萬華</div><h1>把好奇心，<br><em>動手做出來。</em></h1><p>從一塊積木、一行程式開始。<br>這個寒假，讓孩子在創作與挑戰中，<br>找到「原來我做得到」的瞬間。</p><div class="filters"><div class="filter-row"><div><label for="gradeFilter">孩子目前的年級</label><select id="gradeFilter"><option value="">全部年級</option>${[1,2,3,4,5,6].map(n=>`<option value="${n}">國小 ${n} 年級</option>`).join('')}<option value="7">國中以上</option></select></div><div><label for="dateFilter">可參加的日期</label><select id="dateFilter"><option value="">全部日期</option>${camps.map(c=>`<option value="${c.id}">${c.dateLabel}</option>`).join('')}</select></div></div><label class="check"><input id="abilityFilter" type="checkbox">孩子可自行完成 8+ Technic 組裝</label><div class="filter-bottom"><div><p id="count" aria-live="polite"></p><button class="secondary" id="clear" style="min-height:32px;padding:0;border:0;font-size:12px">清除條件</button></div><a class="button" href="#camps">查看符合條件的營隊 ↓</a></div></div></div><div class="hero-photo"><img src="assets/class-960.webp" srcset="assets/class-640.webp 640w, assets/class-960.webp 960w" sizes="(max-width:700px) 100vw, 48vw" width="960" height="720" fetchpriority="high" alt="孩子在教室操作樂高機器人"><div class="photo-note"><strong>小小創作者，大大的可能。</strong><br><span class="hint">每班最多 5 人 · 老師陪伴探索</span></div><p class="photo-caption">歷屆上課情境，非本屆成果</p></div></div></section><div class="wrap facts"><div><strong>01.21 — 02.03</strong><span>三個梯次，各自報名</span></div><div><strong>每天 09:00–16:00</strong><span>含午餐與午休</span></div><div><strong>每班最多 5 人</strong><span>1 人即開班</span></div><div><strong>從零經驗開始</strong><span>依年級與能力選營</span></div></div><section id="camps" class="section wrap"><div class="section-head"><div><div class="eyebrow">FIND THEIR NEXT ADVENTURE</div><h2>三種探索，找到孩子的那一種。</h2></div><p>喜歡動手組裝、想設計遊戲，或第一次接觸機器人，都有適合的起點。</p></div><div class="cards" id="cards"></div></section><section class="section soft"><div class="wrap split"><img class="wide-photo" src="assets/class2.webp" width="960" height="720" loading="lazy" alt="歷屆學員操作樂高作品"><div><div class="eyebrow">LEARN BY MAKING</div><h2>不是只照著做，<br>而是試著想。</h2><p>作品動起來之前，孩子會觀察、提出想法、測試，再調整一次。把遇到的問題變成下一個挑戰，讓學習發生在每一次親手嘗試裡。</p><h3>小班教學，保留每個孩子的節奏</h3><p>每班最多 5 人，讓老師能陪伴孩子理解操作、練習表達自己的發現。</p><span class="hint">照片為歷屆教學情境。</span></div></div></section><section class="section wrap"><div class="eyebrow">HOW TO JOIN</div><h2>從感興趣，到準備好出發。</h2>${process()}</section><section id="info" class="section soft"><div class="wrap"><h2>把一天交給創作，接送交給規畫。</h2>${common()}</div></section><section class="section wrap"><div class="cta"><div><h2>這個寒假，從一個好奇開始。</h2><p>先選營隊，再一起確認孩子的學習起點。</p></div><a class="button" href="#camps">探索三個營隊 ↑</a></div></section>`;
const controls=[$('#gradeFilter'),$('#dateFilter'),$('#abilityFilter')];const saved=new URLSearchParams(location.search);controls[0].value=saved.get('grade')||'';controls[1].value=saved.get('date')||'';controls[2].checked=saved.get('ability')==='1';
function filter(){const [g,d,a]=controls;const list=camps.filter(c=>(!g.value||c.grades.includes(+g.value)||(c.id==='rc'&&a.checked))&&(!d.value||c.id===d.value));$('#count').textContent=`找到 ${list.length} 個適合的營隊`;const q=new URLSearchParams();if(g.value)q.set('grade',g.value);if(d.value)q.set('date',d.value);if(a.checked)q.set('ability','1');history.replaceState(null,'',location.pathname+(q.size?'?'+q:'')+location.hash);try{sessionStorage.setItem('campFilter',q.toString())}catch{}$('#cards').innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h3>目前沒有符合全部條件的營隊</h3><p>試著放寬日期或清除條件；若孩子已有組裝能力，也可勾選 Technic 能力條件。</p><a href="https://lin.ee/NTY6jV8">請老師協助選營 ↗</a></div>'}controls.forEach(c=>c.addEventListener('change',filter));$('#clear').onclick=()=>{controls[0].value='';controls[1].value='';controls[2].checked=false;filter()};filter();}
function card(c){return `<article class="card"><a class="card-image" href="course-${c.id}.html" aria-label="查看${c.name}"><img src="assets/${c.image}" alt="${c.name}課程主題圖" width="800" height="800" loading="lazy"></a><div class="card-body"><span class="tag">${c.batch} / ${c.dates.length} 天 · ${c.tag}</span><h3>${c.name}</h3><p>${c.audience}</p><div class="date">${c.dateLabel}<span class="hint"> / 2027</span></div><p>09:00–16:00 · 含午餐 · 每班最多 5 人</p><p>${c.topics.join(' / ')}</p><div class="price">${c.plans.map(p=>`<div>${priceMarkup(p.price)} <span class="hint">${c.plans.length>1?(p.id==='takehome'?'可帶回':'課堂使用'):c.dates.length+' 天'}</span></div>`).join('')}</div><div class="card-actions"><a href="course-${c.id}.html">查看課程 ↗</a><a class="button" href="${enroll(c)}">立即報名</a></div></div></article>`}
function course(c){let back='index.html#camps';try{const q=sessionStorage.getItem('campFilter');if(q)back='index.html?'+q+'#camps'}catch{}main.innerHTML=`<div class="wrap breadcrumb"><a href="${back}">← 返回營隊總覽</a> / ${c.name}</div><section class="wrap course-hero"><div class="split"><div><div class="eyebrow">2027 WINTER CAMP / ${c.batch}</div><h1>${c.name}</h1><p>${c.intro}</p><div class="chips"><span>${c.dateLabel} · ${c.dates.length} 天</span><span>09:00–16:00</span><span>含午餐</span></div><p><strong>${c.audience}</strong></p><p>${c.plans.map(p=>`${p.name} ${priceMarkup(p.price)}`).join('<br>')}</p><a class="button" href="${enroll(c)}">立即報名 ↗</a><p class="hint" style="margin-top:12px">每班最多 5 人 · 收件後由教室確認名額</p></div><img src="assets/${c.image}" width="800" height="800" alt="${c.name}主題介紹"></div></section><nav class="subnav" aria-label="課程章節"><div class="wrap"><a href="#learn">課程體驗</a><a href="#schedule">每日安排</a><a href="#plans">方案與費用</a><a href="#practical">接送資訊</a><a href="#faq">常見問題</a></div></nav><section id="learn" class="section wrap"><div class="split"><div><div class="eyebrow">CREATE · TEST · DISCOVER</div><h2>把想像，變成自己的作品。</h2><p>${c.description}</p></div><div class="panel"><h3>孩子會練習的三件事</h3>${c.topics.map((t,i)=>`<p><strong>0${i+1}</strong>　${t}</p>`).join('')}<hr><p>適合對象：${c.audience}。${c.id==='rc'?'年級與組裝能力，符合其中一項即可。':'不需相關經驗。'}</p></div></div></section><section id="schedule" class="section soft"><div class="wrap split"><div><div class="eyebrow">A LITTLE MORE EVERY DAY</div><h2>${c.dates.length} 天，讓發現一步步發生。</h2><p>${c.note}</p><p class="hint">每日包含午餐與午休；實際課程依學習情況調整。</p></div><div class="timeline">${c.schedule.map((d,i)=>`<div class="day"><b>${date(c.dates[i])}<br>DAY ${i+1}</b><div><h3>${d[0]}</h3><p>${d[1]}</p></div></div>`).join('')}</div></div></section><section id="plans" class="section wrap"><div class="eyebrow">CHOOSE YOUR EXPERIENCE</div><h2>清楚選方案，安心安排寒假。</h2><div class="plans">${c.plans.map(p=>`<div class="panel"><h3>${p.name}</h3><strong>${priceMarkup(p.price)}</strong><p>${p.detail}</p><p>${c.dates.length} 天・含午餐・09:00–16:00</p><a class="button" href="${enroll(c,p.id)}">選擇此方案，立即報名</a></div>`).join('')}</div><p class="hint" style="margin-top:18px">早托每人每天加 100 元，可於報名時逐日選擇；晚托依實際接回時間另計。</p>${c.id==='rc'?'<div class="notice">兩方案使用不同零件與車型；目前主圖為課程示意。詳細設備型號與各方案實拍將由教室補充，請於繳費前確認。</div>':''}</section><section id="practical" class="section soft"><div class="wrap"><h2>上課前，家長想知道的事。</h2>${common()}</div></section><section id="faq" class="section wrap"><div class="split"><div><div class="eyebrow">GOOD TO KNOW</div><h2>先回答你的幾個問題。</h2><p>還有想了解的地方？<br><a href="${line}">透過 LINE 問問老師 ↗</a></p></div><div><details><summary>需要自備電腦或教具嗎？</summary><p>不需要。Scratch 營由教室提供電腦與帳號；小小樂高工程師營每位孩子使用一套 SPIKE Essential 教具。</p></details><details><summary>作品可以帶回家嗎？</summary><p>遙控車可帶回方案內含市價 3,000 元的正版樂高科技系列越野車及遙控套組（副廠）；SPIKE Prime 課堂使用方案及小小樂高工程師營使用教室教具，作品不帶回。</p></details><details><summary>缺席、轉讓及退費怎麼處理？</summary><p>個人因素缺席無法補課；名額可以轉讓，請先聯絡老師確認接替孩子資格。退費依下列營隊退費辦法辦理。</p></details><details><summary>營隊退費辦法</summary>${refundHtml}</details><details><summary>送出表單就算報名成功嗎？</summary><p>表單送出只是收件；請加入 LINE，告知孩子姓名與報名編號。老師確認名額及付款資訊後，完成繳費並收到教室確認才算完成報名。</p></details></div></div></section><section class="wrap section"><div class="cta"><div><h2>讓孩子的下一個作品，從這裡開始。</h2><p>${c.name} · 2027/${c.dateLabel}</p></div><a class="button" href="${enroll(c)}">立即報名 ↗</a></div></section><div class="mobile-cta"><span>${c.dates.length} 天 · ${c.dateLabel}</span><a class="button" href="${enroll(c)}">立即報名</a></div>`;}
function registration(){const params=new URLSearchParams(location.search),cid=params.get('camp'),pid=params.get('plan');let selected=camps.find(c=>c.id===cid);const invalid=(cid&&!selected)||(pid&&(!selected||!selected.plans.some(p=>p.id===pid)));if(invalid)selected=null;
main.innerHTML=`<div class="wrap"><div class="breadcrumb"><a href="index.html#camps">← 返回營隊總覽</a></div><div class="eyebrow">LET'S MAKE SOMETHING GREAT</div><h1 style="font-size:40px">為孩子，安排一場探索。</h1><p>每次填寫一位孩子、一個營隊。請先核對日期、方案與費用。</p>${invalid?'<p class="notice" role="alert">連結中的營隊或方案無效，請重新選擇。</p>':''}<div class="form-layout"><aside><div class="panel summary-box"><h2>你的營隊選擇</h2><div id="summary">請先選擇營隊。</div><p class="hint">送出資料後，仍需透過 LINE 確認名額與繳費。</p></div></aside><form id="registration"><div class="notice">${config.registrationOpen?'收件不等於完成報名，名額與付款由老師確認。':'報名尚未開放。你可以先查看與試填，資料不會送出或保存在此裝置。請透過 LINE 洽詢。'}</div><fieldset><legend>01　選擇營隊與方案</legend><label for="camp">營隊 *</label><select name="camp" id="camp" required><option value="">請選擇營隊</option>${camps.map(c=>`<option value="${c.id}">${c.name}｜${c.dateLabel}</option>`).join('')}</select><div class="field" style="margin-top:18px"><label for="plan">方案 *</label><select id="plan" name="plan" required><option value="">請先選營隊</option></select></div><label>預約早托（選填）</label><p class="hint">08:00–08:30，每個日期加 100 元；08:30 後一般到班免早托費。</p><div id="early" class="dates"></div></fieldset><fieldset><legend>02　孩子的資料</legend><div class="field-grid">${field('child','孩子姓名 *','text',true)}<div class="field"><label for="grade">年級 *</label><select id="grade" name="grade" required><option value="">請選擇</option>${[1,2,3,4,5,6].map(n=>`<option value="${n}">國小 ${n} 年級</option>`).join('')}<option value="7">國中以上</option><option value="0">其他／尚未入小學</option></select></div></div>${field('school','學校（選填）')}<label for="experience">相關經驗</label><select id="experience" name="experience"><option value="none">第一次接觸</option><option value="some">曾接觸組裝或程式</option></select><label id="abilityRow" class="check" hidden><input type="checkbox" name="ability">孩子能自行完成標示 8+ 的 LEGO Technic 組裝（未達三年級須符合）</label><p id="eligibility" class="error" aria-live="polite"></p></fieldset><fieldset><legend>03　家長與緊急聯絡</legend><div class="field-grid">${field('parent','家長稱呼 *','text',true)}${field('phone','手機 *','tel',true)}${field('email','Email *','email',true)}${field('emergencyName','緊急聯絡人 *','text',true)}${field('emergencyPhone','緊急聯絡電話 *','tel',true)}</div><p class="hint">Email 用於寄送收件通知，請核對拼字；電話用於報名及緊急聯繫。</p></fieldset><fieldset><legend>04　其他需求與確認</legend>${field('referral','推薦人（選填）')}<p class="hint">可填「某某孩子的媽媽／爸爸」。</p><label for="diet">特殊飲食／過敏需求（選填）</label><textarea id="diet" name="diet" maxlength="500"></textarea><label for="notes">需協助事項（選填）</label><textarea id="notes" name="notes" maxlength="500"></textarea><details><summary>個人資料使用說明</summary><p>資料由創意方塊機器人教室用於本次營隊報名、聯繫、接送及緊急處理，保存於非公開管理表，僅授權人員處理。你可透過 LINE 要求查詢、更正或刪除；不提供必要資料將無法受理報名。不包含行銷或照片使用授權。保存期限與完整告知事項將於開放前補齊。</p></details><details open><summary>營隊退費辦法（報名前請閱讀）</summary>${refundHtml}</details><label class="check"><input name="privacy" type="checkbox" required>我已閱讀個人資料使用說明，並同意用於本次報名與聯繫。*</label><label class="check"><input name="rules" type="checkbox" required>我已閱讀並同意上述營隊退費辦法；了解收件不代表保留名額，須完成繳費與教室確認。*</label><label id="outdoorRow" class="check" hidden><input name="outdoor" type="checkbox">我了解遙控車營安排戶外活動；教室提供地點、交通與雨備後，須另行取得我的同意。</label></fieldset><p id="formStatus" class="status error" role="alert"></p><button type="submit" id="submit">送出報名資料</button> <a href="${line}">LINE 洽詢 ↗</a></form></div></div>`;
const form=$('#registration');if(selected)$('#camp').value=selected.id;
function update(reset=true){const c=camps.find(c=>c.id===$('#camp').value);if(reset){$('#plan').innerHTML=c?'<option value="">請選擇方案</option>'+c.plans.map(p=>`<option value="${p.id}">${p.name}｜${money(campTotal(p.price))}${earlyBirdDiscount()?'（早鳥價）':''}</option>`).join(''):'<option value="">請先選營隊</option>';if(c?.plans.length===1)$('#plan').value=c.plans[0].id;$('#early').innerHTML=c?c.dates.map(d=>`<label class="check"><input type="checkbox" name="early" value="${d}">${date(d)}</label>`).join(''):'';form.elements.outdoor.checked=false;form.elements.ability.checked=false;}$('#abilityRow').hidden=c?.id!=='rc';$('#outdoorRow').hidden=c?.id!=='rc';form.elements.outdoor.required=c?.id==='rc';const p=c?.plans.find(p=>p.id===$('#plan').value),early=form.querySelectorAll('[name=early]:checked').length;$('#summary').innerHTML=c?`<h3>${c.name}</h3><p>2027/${c.dateLabel} · ${c.dates.length} 天<br>09:00–16:00<br>${c.audience}</p><p>${p?p.name:'請選擇方案'}</p>${p?`<p>原方案費用：${money(p.price)}<br><span id="earlyDiscount">早鳥優惠折抵：−${money(earlyBirdDiscount())}</span></p>`:''}<p>早托 ${early} 天：${money(early*100)}</p><div class="total">${p?money(campTotal(p.price,early)):'—'}</div><p class="hint">含午餐，晚托另計。</p>`:'請先選擇營隊。';const g=Number(form.elements.grade.value);const ok=!c||!form.elements.grade.value||c.grades.includes(g)||(c.id==='rc'&&form.elements.ability.checked);$('#eligibility').textContent=ok?'':'目前不符合所選營隊資格，請調整選擇或聯絡老師。';form.elements.grade.setCustomValidity(ok?'':'請確認孩子符合營隊參加條件。');}
document.addEventListener('early-bird-ended',()=>{if(!document.contains(form))return;const c=camps.find(c=>c.id===$('#camp').value);if(c)for(const o of $('#plan').options){const p=c.plans.find(p=>p.id===o.value);if(p)o.textContent=p.name+'｜'+money(p.price)}update(false)});$('#camp').onchange=()=>update();form.addEventListener('change',e=>{if(e.target.id!=='camp')update(false)});update();if(selected&&pid&&!invalid){$('#plan').value=pid;update(false)}$('#submit').disabled=!config.registrationOpen||!config.endpoint;
let requestId=null,pendingPayload=null;
form.onsubmit=async e=>{e.preventDefault();if(!config.registrationOpen||!config.endpoint)return;update(false);if(!form.reportValidity())return;const values=Object.fromEntries(new FormData(form));values.early=[...form.querySelectorAll('[name=early]:checked')].map(x=>x.value);for(const k of ['privacy','rules','outdoor','ability'])values[k]=form.elements[k].checked;values.consentVersion=config.consentVersion;const signature=JSON.stringify(values);if(pendingPayload&&pendingPayload!==signature){$('#formStatus').textContent='上一筆送出結果尚未確認。請恢復原資料重試，或透過 LINE 請老師查核，避免重複登記。';return}requestId??=crypto.randomUUID();pendingPayload=signature;$('#submit').disabled=true;$('#formStatus').textContent='正在送出，請稍候…';const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),20000);try{const res=await fetch(config.endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify({...values,requestId}),signal:ctrl.signal});const data=await res.json();if(!res.ok||!data.ok){if(data.saved===false){pendingPayload=null;requestId=null}throw new Error(data.message||'尚未確認收件，請稍後重試。')}if(!data.registrationId)throw new Error('回應缺少收件編號，請聯絡教室核對。');const message=`老師您好，我已填寫 2027 冬令營報名表，請協助確認報名狀態與繳費方式。\n報名編號：${data.registrationId}\n孩子姓名：${values.child}\n營隊：${data.campName}\n日期：${data.dateLabel}\n方案：${data.planName}\n謝謝老師！`;main.innerHTML=`<section class="success panel"><div class="eyebrow">RECEIVED · 下一步，聯絡老師</div><h1 style="font-size:36px" tabindex="-1">報名資料已收到</h1><p>報名編號：<strong>${esc(data.registrationId)}</strong><br>${esc(data.campName)} · ${esc(data.dateLabel)}<br>${esc(data.planName)} · ${money(data.total)}</p><div class="notice">還差一步：請主動傳送 LINE 訊息。只加入好友，老師無法主動與你對話；請複製下方文字，加入 LINE 後貼上並按「傳送」。老師收到訊息後，才能核對孩子的報名狀態。名額仍須經繳費與教室確認。</div><label for="lineMessage">① 複製下方報名確認訊息</label><textarea id="lineMessage" rows="9" readonly style="min-height:230px;line-height:1.8">${esc(message)}</textarea><button id="copy" class="secondary">複製報名確認訊息</button><p id="copyStatus" aria-live="polite"></p><p><a class="button line" href="${line}" target="_blank" rel="noopener">② 加入／開啟教室 LINE ↗</a></p><p><strong>③ 在對話中貼上訊息，並按「傳送」。</strong></p><p class="hint">已是好友可直接開啟對話。複製或加入好友不會自動傳送訊息，請務必完成第 ③ 步。</p></section>`;$('h1').focus();$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText(message);$('#copyStatus').textContent='已複製！請開啟教室 LINE，貼上後務必按「傳送」。'}catch{$('#lineMessage').select();$('#copyStatus').textContent='請長按或手動複製上方訊息。'}};}catch(err){$('#formStatus').textContent=err.name==='AbortError'?'連線逾時，收件結果尚未確認。資料已保留在本頁；請勿關閉，可用相同資料重試，或聯絡老師查核。':err.message;$('#submit').disabled=false;}finally{clearTimeout(timer)}};
}
function field(name,label,type='text',required=false){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" ${required?'required':''} maxlength="${type==='email'?120:80}" ${type==='tel'?'pattern="[0-9+() -]{8,20}" inputmode="tel"':''}></div>`}
try{const r=await fetch('camps.json');if(!r.ok)throw Error();camps=await r.json();const view=document.body.dataset.view;if(view==='home')home();else if(view==='course')course(camps.find(c=>c.id===document.body.dataset.camp));else registration();}catch{main.innerHTML='<div class="wrap section"><h1>營隊資訊暫時無法載入</h1><p>請重新整理頁面，或透過 LINE 聯絡教室。</p><a href="https://lin.ee/NTY6jV8">LINE 聯絡教室</a></div>'}


let earlyWasActive=earlyBirdDiscount()>0;
function tickEarlyBird(){const banner=$('#earlyBird'),clock=$('#earlyClock');if(!banner||!clock)return;const left=Math.max(0,EARLY_BIRD_END-Date.now());if(!left){banner.innerHTML='<div class="wrap"><strong>早鳥優惠已截止，目前以原價報名。</strong></div>';if(earlyWasActive){earlyWasActive=false;document.querySelectorAll('[data-base-price]').forEach(el=>el.textContent=money(Number(el.dataset.basePrice)));document.dispatchEvent(new Event('early-bird-ended'));}return;}const sec=Math.floor(left/1000),d=Math.floor(sec/86400),h=Math.floor(sec%86400/3600),m=Math.floor(sec%3600/60),s=sec%60;clock.textContent=`${d} 天 ${String(h).padStart(2,'0')} 時 ${String(m).padStart(2,'0')} 分 ${String(s).padStart(2,'0')} 秒`;}
tickEarlyBird();setInterval(tickEarlyBird,1000);document.addEventListener('visibilitychange',tickEarlyBird);
